package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net/http"
	"strings"
	"sync"
)

type User struct {
	Username string
	Role     string
	APIKey   string
}

type Document struct {
	ID      string
	Owner   string
	Content string
	Secret  bool
}

var (
	users     = map[string]*User{}
	documents = map[string]*Document{}
	mu        sync.RWMutex
)

func init() {
	users["ak_admin_001"] = &User{Username: "admin", Role: "admin", APIKey: "ak_admin_001"}
	users["ak_user_002"] = &User{Username: "alice", Role: "user", APIKey: "ak_user_002"}
	documents["doc1"] = &Document{ID: "doc1", Owner: "admin", Content: "Top Secret Plan", Secret: true}
	documents["doc2"] = &Document{ID: "doc2", Owner: "alice", Content: "Public Notes", Secret: false}
}

func generateID() (string, error) {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// authenticateRequest validates the API key and returns the user
func authenticateRequest(r *http.Request) *User {
	apiKey := r.Header.Get("X-API-Key")
	if apiKey == "" {
		return nil
	}
	mu.RLock()
	defer mu.RUnlock()
	return users[apiKey]
}

// securityMiddleware performs authentication and path-based authorization
// Authorization is checked AFTER path normalization to prevent bypass
func securityMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		user := authenticateRequest(r)
		if user == nil {
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}

		// Use the cleaned path from net/http (already decoded once)
		// r.URL.Path is the canonical decoded path - use it directly
		// for both authorization AND routing (same path, no discrepancy)
		cleanPath := r.URL.Path

		// Reject any path that still contains percent-encoding
		// This prevents double-encoding attacks entirely
		if strings.Contains(r.URL.RawPath, "%") {
			http.Error(w, "Invalid path encoding", http.StatusBadRequest)
			return
		}

		// Path-based authorization on the canonical path
		if strings.HasPrefix(cleanPath, "/admin/") || strings.HasPrefix(cleanPath, "/internal/") {
			if user.Role != "admin" {
				http.Error(w, "Forbidden", http.StatusForbidden)
				return
			}
		}

		// Store user in context via header rewriting (simplified)
		r.Header.Set("X-Verified-User", user.Username)
		r.Header.Set("X-Verified-Role", user.Role)
		next.ServeHTTP(w, r)
	})
}

// router dispatches requests based on the same r.URL.Path used by middleware
func router(w http.ResponseWriter, r *http.Request) {
	// Use the SAME path that middleware authorized - r.URL.Path
	// No additional decoding/normalization step
	path := r.URL.Path

	switch {
	case strings.HasPrefix(path, "/admin/documents/delete/"):
		handleAdminDelete(w, r, path)
	case strings.HasPrefix(path, "/admin/documents/list"):
		handleAdminList(w, r)
	case strings.HasPrefix(path, "/internal/secrets"):
		handleInternalSecrets(w, r)
	case strings.HasPrefix(path, "/documents/"):
		handleGetDocument(w, r, path)
	case path == "/documents" && r.Method == "POST":
		handleCreateDocument(w, r)
	default:
		http.NotFound(w, r)
	}
}

func handleAdminDelete(w http.ResponseWriter, r *http.Request, path string) {
	docID := strings.TrimPrefix(path, "/admin/documents/delete/")
	if docID == "" {
		http.Error(w, "Missing document ID", http.StatusBadRequest)
		return
	}
	// Validate docID format
	if !isValidDocID(docID) {
		http.Error(w, "Invalid document ID", http.StatusBadRequest)
		return
	}
	mu.Lock()
	defer mu.Unlock()
	if _, exists := documents[docID]; !exists {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}
	delete(documents, docID)
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Deleted %s", docID)
}

func isValidDocID(id string) bool {
	if len(id) == 0 || len(id) > 64 {
		return false
	}
	for _, c := range id {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
			return false
		}
	}
	return true
}

func handleAdminList(w http.ResponseWriter, r *http.Request) {
	mu.RLock()
	defer mu.RUnlock()
	var result []string
	for id, doc := range documents {
		result = append(result, fmt.Sprintf("%s (owner=%s, secret=%v)", id, doc.Owner, doc.Secret))
	}
	fmt.Fprintf(w, "Documents:\n%s", strings.Join(result, "\n"))
}

func handleInternalSecrets(w http.ResponseWriter, r *http.Request) {
	mu.RLock()
	defer mu.RUnlock()
	var result []string
	for id, doc := range documents {
		if doc.Secret {
			result = append(result, fmt.Sprintf("%s: %s", id, doc.Content))
		}
	}
	fmt.Fprintf(w, "Secrets:\n%s", strings.Join(result, "\n"))
}

func handleGetDocument(w http.ResponseWriter, r *http.Request, path string) {
	docID := strings.TrimPrefix(path, "/documents/")
	if !isValidDocID(docID) {
		http.Error(w, "Invalid document ID", http.StatusBadRequest)
		return
	}
	mu.RLock()
	defer mu.RUnlock()
	doc, exists := documents[docID]
	if !exists {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}
	user := r.Header.Get("X-Verified-User")
	if doc.Secret && doc.Owner != user {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}
	fmt.Fprintf(w, "Document %s: %s", doc.ID, doc.Content)
}

func handleCreateDocument(w http.ResponseWriter, r *http.Request) {
	content := r.FormValue("content")
	if len(content) > 10000 {
		http.Error(w, "Content too large", http.StatusBadRequest)
		return
	}
	secret := r.FormValue("secret") == "true"
	user := r.Header.Get("X-Verified-User")

	id, err := generateID()
	if err != nil {
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}

	doc := &Document{
		ID:      id,
		Owner:   user,
		Content: content,
		Secret:  secret,
	}
	mu.Lock()
	documents[doc.ID] = doc
	mu.Unlock()
	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, "Created %s", doc.ID)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/", router)

	server := &http.Server{
		Addr:    ":8080",
		Handler: securityMiddleware(mux),
	}
	server.ListenAndServe()
}
